(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["eu"] = {"ui":{"skip":"Joan edukira","back":"← Itzuli AI-gilera","lang.button":"Hizkuntza: {name}","lang.dialog":"Aukeratu hizkuntza bat","lang.search":"Bilatu hizkuntzak","lang.none":"Ez dago hizkuntzarik bat datorrenik","lang.notYet":"{name} ez dago oraindik itzulita","theme.aria":"Aldatu gai argiaren eta ilunaren artean","theme.toLight":"Aldatu gai argira","theme.toDark":"Aldatu gai ilunera","words.underline":"Azpimarratu hitz hauek orrian","words.underlineHelp":"Pasatu sagua edo sakatu puntuz azpimarratutako hitz baten gainean, zer esan nahi duen ikusteko.","index.title":"AI-gile: zure AI garapen-taldea, taula bakarrean","index.description":"AI-gile AA bidezko programazio-taldeentzako kanban taula bat da. Zu lo zaudela lan egiten dute; zuk pila labur bat jasotzen duzu, erabaki, probatu eta onartzeko gauzekin.","hero.logoAlt":"AI-gile taularen ikonoa","hero.h1.html":"Zure AI garapen-taldea, taula&nbsp;bakarrean.","hero.alpha":"🐣 Aurre-alfa itxia","hero.alphaTitle":"Goiztiarra eta bukatu gabea: eskerrik asko probatzeagatik!","hero.lede":"Zu lo zaudela eraikitzen dute. Esnatzean pila labur bat izango duzu zain: galdera batzuk, probatzeko gauza batzuk, diamante more bat edo bi. Klik egin, onartu, eta itzuli zure kafera.","dl.windows":"Windows aplikazioa","dl.browser":"Erabili nabigatzailean","dl.soon":"Laster","dl.notify":"🔔 Abisatu irekitzen denean","dl.notifySmall":"Alfa edo beta","hero.secondary":"Agile, baina taldeak ez du inoiz zutik egindako bilerako kafearen beharrik. (Zutik egindako bilerak egiten dituzte, hala ere.)","pitch.h2":"AI-gile nahi adina hitzetan","pitch.lede":"Aukeratu luzera bat, hitz batetik 144ra. Luzera bakoitza bere deskribapena da, tamaina horretarako idatzia. Arrastatu graduatzailea edo erabili gezi-teklak.","pitch.rangeLabel":"Luzera hitzetan","pitch.dice":"🎲 beste bertsio bat","pitch.words.one":"{n} hitz","pitch.words.other":"{n} hitz","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letra","pitch.chars.one":"{n} karaktere","pitch.chars.other":"{n} karaktere","count.line.html.one":"{n} txartel taulan orain","count.line.html.other":"{n} txartel taulan orain","features.aria":"Zer egiten duen","f.pile.h":"Pila bakarra zuretzat","f.pile.html":"<b>Zuretzat</b> atalak zure zain dagoen guztia biltzen du, proiektu guztietatik: galderak, probatzeko gauzak, gizakiak bakarrik egin ditzakeen zereginak. Zure ilarak esaten dizu zer datorren eta zenbat denbora behar duen.","f.sleep.h":"Zu lo zaudela lan egiten duten taldeak","f.sleep.p":"Proiektu bakoitzak taldeburu bat eta AA agenteen talde bat ditu. Egin iruzkina txartel batean eta taldea esnatu egingo da, lana egin eta itzuliko dizu gizaki nekatu batek jarrai ditzakeen urratsekin.","f.tester.h":"AA probatzaile batek aurretik egiaztatzen du","f.tester.p":"Ezer zuregana iritsi aurretik, probatzaile batek aplikazioaren kopia batean urratsak jarraitzen ditu eta ikusi duena erakusten du, pantaila-argazkiarekin. Begiratu pasatakoak azkar eta onartu klik batekin.","f.proof.h":"Frogak, ez promesak","f.proof.p":"Entrega bakoitzak zer aldatu den erakusten du: fitxategiak, diff-a, pantaila-argazkiak. Ez duzu aplikazio bakoitza ireki behar bukatuta dagoen jakiteko.","f.chat.h":"Berriketan zure taldeburuekin","f.chat.p":"Discord estiloko barra bat: ikono bat proiektu bakoitzeko, diamante moreak zu behar zaituenarentzat. Bidali ideia bat taldeburuari; txartel eta plan bihurtuko du, ✅ Go botoiarekin.","f.tidy.h":"Bere burua txukun mantentzen du","f.tidy.p":"Elkarrekin lotutako txartelak bat egiten dute, titulu nahasiak zuzentzen dira, eta token-kontrolak kodea arin mantentzen du. Aldatzeko gauza gutxiago, pentsatzeko gutxiago.","f.private.h":"Zurea, zure ordenagailuan","f.private.li1":"Taula zure makinan exekutatzen da eta zuri bakarrik erantzuten dio.","f.private.li2":"Pertsonen arteko mezu pribatuak muturretik muturrera zifratuta daude.","f.private.li3":"Konturik gabe, aztarnaririk gabe, cookierik gabe.","f.lang.h":"Zure hizkuntzan","f.lang.p":"120 hizkuntza baino gehiago, nederlanderatik, galesetik eta japonieratik piratera, Yodara eta klingonera, garatzaileen hitzetarako ingelesera itzultzeko aldaketa azkarrarekin.","tl.aria":"Denbora-lerroa lehen elkarrizketatik ibilbide-orrira","tl.h2":"Lehen txatetik datorrenera","tl.lede":"Benetako datak eta orduak, zure ordu-zonan. Gaurtik aurrera plana da, daturik agindu gabe.","tl.today":"Gaur","tl.planned":"planifikatuta","tl.cards.one":"{n} txartel","tl.cards.other":"{n} txartel","join.h2":"Egin bat","join.lede":"AI-gile gizaki txiki batek eta agente pazientzia handiko askok eraikitzen dute. Pribatua da oraingoz, lagunekin alfa itxian. Probatu nahiko zenuke irekitzen denean?","join.btn":"Eman interesa","join.small":"Posta elektronikoz idatziko dizugu, besterik ez","footer.tag":"AI-gile. Aztarnaririk gabe, cookierik gabe, zutik egindako bilerako kaferik gabe.","footer.licence":"Negozio-lizentzia","footer.status":"Egoera","footer.privacy":"Zer gordetzen dugun","form.sending":"Bidaltzen…","form.failed":"Hori ez da ondo atera: saiatu berriro geroago.","form.offline":"Ezin izan da AI-gilerekin konektatu: saiatu berriro geroago.","form.keep":"Zuri erantzuteko bakarrik erabiltzen dugu, eta gero ezabatu egiten dugu. Aztarnaririk gabe, cookierik gabe.","form.keepLink":"Zer gordetzen dugun","interest.title":"AI-gile: abisatu alfa irekitzen denean","interest.description":"Utzi zure posta elektronikoa AI-gileren alfa edo beta itxia noiz irekitzen den jakiteko.","interest.h1":"🔔 Abisatu irekitzen denean","interest.lede":"AI-gile aurre-alfa itxian dago. Utzi zure posta elektronikoa eta behin idatziko dizugu, zuretzako lekua dagoenean.","interest.email":"Zure posta elektronikoa","interest.which":"Zein proba?","interest.alpha":"Alfa itxia: goiztiarra, latza, aldaketa asko","interest.beta":"Beta: egonkorragoa, geroagokoa","interest.both":"Edozein, zein lehenago ireki","interest.submit":"Jarri nazazu zerrendan","interest.thanks":"Eskerrik asko! Zerrendan zaude.","licence.title":"AI-gile: negozio-lizentzia","licence.description":"Erabiltzen al duzu AI-gile zure negozioan? Eskatu negozio-lizentzia doakoa.","licence.h1":"📜 Negozio-lizentzia","licence.lede":"Lanean erabiltzen al duzu AI-gile? Esan zeintzuk zareten eta zer egiten duzuen. Onik egiten badu, lizentzia doakoa da.","licence.company":"Enpresa","licence.website":"Webgunea","licence.what":"Zer egiten duzuen","licence.how":"Nola laguntzen dion munduari","licence.email":"Posta elektronikoa","licence.submit":"Eskatu","licence.thanks":"Eskerrik asko! Posta elektronikoz erantzungo dizugu.","status.title":"AI-gile egoera","status.h1":"AI-gile egoera","status.quiet":"Dena lasai","status.intro":"AI-gile badabil orain? Orri honek 5 minuturo egiaztatzen ditu webgunea, taulak partekatzea, deiak eta deskarga.","status.up":"Badabil ({ms} ms-tan erantzun du)","status.slow":"Ez dio azken egiaztapenari erantzun, berriro saiatzen","status.down":"Erorita: ez die azken bi egiaztapenei erantzun","status.svc.web":"Webgunea","status.svc.web.offers":"Gune hau: zer den AI-gile, eta interes-formularioa","status.svc.boards":"Taulak partekatzea","status.svc.boards.offers":"Taula publikoak, lagunen arteko mezuak eta gonbidapenak","status.svc.calls":"Deiak","status.svc.calls.offers":"Ahotsa, bideoa eta pantaila partekatzea AI-gile-n","status.svc.download":"Deskarga","status.svc.download.offers":"Windowserako instalatzailea eta gonbidapen-estekak","status.checking":"Egiaztatzen…","status.offline":"Ezin da egoera-zerbitzura heldu orain (berriro saiatzen)","status.updated":"eguneratua {ago}","status.justNow":"orain bertan","status.min":"duela {n} min","status.hours":"duela {n} h","status.days":"duela {n} egun","privacy.title":"AI-gile: zer gordetzen dugun","privacy.h1":"Zer gordetzen dugun","privacy.lede":"Laburbilduz: bidaltzen diguzuna bakarrik, eta ez denbora luzez.","privacy.only":"Bidaltzen diguzuna bakarrik: formulario batean idazten duzuna, zure posta elektronikoa adibidez. Zuri buruzko beste ezer ez.","privacy.sealed":"Zigilatu egiten da, gure zerbitzariak irakurri ez dezan: zure nabigatzailean, irten aurretik (nabigatzaile zaharrago batean, iristen den unean). Gure taulak bakarrik ireki dezake.","privacy.server":"Zerbitzaritik ezabatzen da gure taulara iritsi bezain laster. 30 egunen ondoren oraindik han dagoena ere ezabatu egiten da, hala ere.","privacy.board":"Gure taulan gordetzen dugu zuri erantzun arte bakarrik, eta gero handik ere ezabatzen dugu.","privacy.none":"Aztarnaririk gabe, cookierik gabe, analitikarik gabe.","privacy.local":"Zure hizkuntza eta modu argiaren edo ilunaren aukera zure nabigatzailean bertan geratzen dira. Ez zaizkigu inoiz bidaltzen.","privacy.ask":"Lehenago ezabatzea nahi duzu? Erantzun gure mezu elektronikoari eta esaiguzu.","live.h2":"Ikusi nola eraikitzen den, zuzenean","live.caption":"Txartel guztiak ezkutuan daude: lanaren forma ikusten duzu, ez hitzak.","live.watching.one":"zuzenean: {n} ikusten","live.watching.other":"zuzenean: {n} ikusten","live.last.now":"Azken txartela orain bertan mugitu da","live.last.min.one":"Azken txartela duela {n} min mugitu da","live.last.min.other":"Azken txartela duela {n} min mugitu da","live.last.hour.one":"Azken txartela duela {n} ordu mugitu da","live.last.hour.other":"Azken txartela duela {n} ordu mugitu da","live.last.day.one":"Azken txartela duela {n} egun mugitu da","live.last.day.other":"Azken txartela duela {n} egun mugitu da","live.offline":"Zuzeneko taulak atsedentxo bat hartzen ari da. Itzuli laster.","live.cols":"Backlog|Egiteko|Egiten|Taldeak aztertzen|Zuk probatzeko|Taldearentzat|Eginda"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotak.","Delegatuta."]},{"n":2,"texts":["Robotak lanean.","Agenteak, antolatuta.","Ideiak, eraikita."]},{"n":3,"texts":["Kanbana robotentzat.","Ideiak ezaugarri bihurtzen.","Agente-kanban doakoa."]},{"n":5,"texts":["Agenteek zuzendutako kanban taula.","Zuk idatzi, agenteek eraiki.","Doakoa, lokala, probatua, apur bat zentzugabea."]},{"n":8,"texts":["AA agenteek lan egiten duten kanban taula doakoa.","Idatzi ideia bat. Agenteek eraikiko dute. Zuk onartu.","Agile gizaki batentzat eta robot pazientzia handiko askorentzat."]},{"n":13,"texts":["Zure ordenagailuko kanban taula, non AA agenteek txartelak hartzen eta lana egiten duten.","Idatzi ideia bat. Agenteen talde batek eraikiko du. Probatzaile batek egiaztatuko du.","Doakoa, konturik gabe, aztarnaririk gabe: taula bat, robot batzuk, eta zu agintean."]},{"n":21,"texts":["AI-gile AA bidezko programazio-agenteekin lan egiteko kanban taula bat da. Haiek hartzen dituzte txartelak; zuk probatu eta onartzen dituzu.","Proiektu bakoitzak taldeburu bat eta AA agenteen talde bat izaten ditu. Egin iruzkina edozein txartelean eta taldea lanean hasiko da.","Zure ordenagailuan exekutatzen den zeregin-taula pertsonal eta doakoa, konturik eta aztarnarik gabekoa. Langileak robotak dira. Baiezkoa ematen duena zu zara."]},{"n":34,"texts":["Ideiak taulan jartzen dituzu. AA agenteen talde batek ezaugarri funtzionaletan bihurtzen ditu, probatu egiten ditu eta probatzeko urratsekin itzultzen dizkizu. Ezer ez da bukatutzat jotzen zuk esan arte.","AI-gile etxean egindako kanban taula bat da, Richek eraiki zuena orain kudeatzen dituen agenteen laguntza handiarekin. Doakoa da, zure ordenagailuan exekutatzen da eta lagunekin partekatzen da, ez saltzen.","Imajinatu ohiko kanban taula bat, Backlogetik Eginda arteko zutabeekin, baina txartelak AA agenteek hartzen dituztela. Aurrerapenaren berri ematen dute, galdetzen dute trabatuta daudenean, eta beti zure baiezkoaren zain geratzen dira."]},{"n":55,"texts":["AI-gile kanban taula bat da, eta bertako taldea AA agenteek osatzen dute. Proiektu bakoitzak lana planifikatzen duen taldeburu bat eta eraikitzen duten laguntzaile batzuk ditu. Ezaugarri bat prest dagoenean, AA probatzaile batek probatu eta pantaila-argazkia ateratzen du, eta gero zure pilara iristen da. Onartu, edo egin iruzkina eta berriro lantzen dute.","Pertsona baten modua izan zen aldi berean AA bidezko programazio-saio asko jarraitzeko, eta benetako taula bihurtu zen. Zure makinan exekutatzen da, ez du konturik behar eta ez dauka aztarnaririk. Doakoa da lagunentzat eta jakin-minez daudenentzat. Bukatu gabe ere badago, beraz espero ertz latz batzuk eta noizbehinkako sorpresaren bat.","Hau da bertsio zintzoa. Zuk bururatu behar dituzu oraindik ideiak, eta zuk egiaztatu behar dituzu emaitzak. AI-gilek tartean dagoen guztia egiten du: txartelak ordenean mantentzen ditu, agente egokia esnatzen du iruzkina egitean, zehazki zer aldatu den erakusten du, eta dena pila labur batean uzten du zuretzat."]},{"n":89,"texts":["AI-gile zure ordenagailuan exekutatzen duzun kanban taula doakoa da. Pertsonen ordez, proiektu bakoitzak AA agenteen talde bat du: zure ideiak txartel eta plan bihurtzen dituen taldeburu bat, eta txartelak lehentasun-ordenan hartzen dituzten laguntzaileak. Zerbait eraikita dagoenean, AA probatzaile batek proba-urratsak jarraitzen ditu eta ikusi duena erakusten dizu. Gero Zuretzat izeneko pila batean geratzen da zain. Onartzen duzu, edo iruzkina egiten duzu eta taldeak berriro saiatzen da. Ezer ez da inoiz Eginda zutabera iristen zu gabe.","Ez dituzun espero agian gauza batzuk. Gaueko zaintzak Egiteko zutabea beteta mantentzen du zu lo zaudela, zure erantzunik behar ez duten txartelak aukeratuz. Token-kontagailuak erakusten du agenteek gaur eta aste honetan zenbat erabili duten, eta Token-gabeko Moduak gastatzeari uzteko esaten die. Lagunei mezuak bidal diezazkiezu, eta mezu pribatuak muturretik muturrera zifratuta daude. Taulak 120 hizkuntza inguru hitz egiten ditu, nederlandera, flandestarra, pirata eta klingonera barne. Horietako ezerk ez du zentimorik balio, eta inork ez dizu saltzen saiatzen ere.","AI-gile proiektu txiki eta pertsonala da, ez enpresa bat. Richek AA bidezko programazio-proiektu batzuk zaindu nahi zituen aplikazio bakoitza irekitzeke zer moduz zeuden begiratzeko, beraz berak eta agenteek horretarako taula bat eraiki zuten, eta gero taula bera erabili zuten gainerakoa eraikitzeko. Aurre-alfa itxian dago, hau da, funtzionatzen du, gehienetan, lagun sorta txiki batentzat. Ez dago prezio-orririk, ez albisteak bidaltzen dituenik eta ez hazkunde-planik. Erabilgarria iruditzen bazaizu, probatzeko eskatu dezakezu apur bat gehiago irekitzen denean."]},{"n":144,"texts":["AI-gile gizaki bakar batentzako eta AA agente askorentzako kanban taula bat da. Zure ordenagailuan exekutatzen da eta guztiz doakoa da. Proiektuak gehitzen dituzu, eta proiektu bakoitzak taldeburu bat eta talde txiki bat izaten ditu. Taldeburuarekin berriketan aritzen zara, Discorden antzera, eta ideia bat deskribatzen duzu; taldeburuak txartel eta plan bihurtzen du, eta Go sakatzeko zain geratzen da. Taldeak txartelak lehentasun-ordenan egiten ditu, hizkuntza-ereduentzat egindako komando-lerro sinple bat erabiliz. Ezer zuregana itzuli aurretik, AA probatzaile batek aplikazioaren kopia batean urratsak jarraitzen ditu eta pantaila-argazki bat eransten du. Amaitutako lana zure pilara iristen da, aldatutako fitxategiekin eta diff-arekin. Onartzen duzu, edo iruzkin bat uzten duzu eta taldea esnatu eta berriro saiatzen da. Zuk bakarrik mugi dezakezu txartel bat Eginda zutabera.","AI-gilerekin egun bat, gutxi gorabehera. Arratsaldean iruzkin batzuk uzten dituzu: botoi hau toki okerrean dago, zerrenda hori ordenatu beharko litzateke, modu iluna izan genezake. Ohera zoaz. Agenteek iruzkinak irakurtzen dituzte, aldaketak egiten dituzte, probatzen dituzte eta itzultzen dizkizute. Egiteko zutabea hustuz gero, gaueko zaintzak backlogetik betetzen du, zure erantzunik behar ez duten txartelekin. Goizean pila labur bat dago: galdera pare bat eta probatzeko gauza batzuk, bakoitza lo gaizto dagoen pertsona batek jarrai ditzakeen urratsekin eta funtzionatzen duela erakusten duen pantaila-argazkiarekin. Klik eginez igarotzen zara, onak onartzen dituzu eta gainerakoak itzultzen dituzu. Token-kontagailuak erakusten du horrek guztiak zer erabili duen, eta Token-gabeko Modua aste mehe horietarako dago. Gero gosaltzen duzu, agenteek oraindik laguntzen ezin dutena. Kafea, berriz, lasai edan dezakezu.","Lehenik, zer ez den AI-gile. Ez da startup bat, ez dago salgai, eta inork ez ditu zure datuak biltzen. Zure ordenagailuan exekutatzen den taula doakoa da, konturik gabe, aztarnaririk gabe eta cookierik gabe. Zer den: AA bidezko programazio-proiektu guztiak aldi berean ikusteko leku txukun bat, agente-talde batek txartelak egiten dituela eta zuk erabakiak hartzen dituzula. Lotutako txartelak batzen ditu, titulu nahasiak zuzentzen ditu, eta kodea zein arin mantentzen den zaintzen du. 120 hizkuntza inguru hitz egiten ditu, nederlandera eta flandestarretik pirata eta klingonera. Lagunek elkarri mezuak bidal diezazkiokete, pribatuki eta zifratuta. Richek eta agente pazientzia handiko askok eraiki zuten, gehienbat bera bera erabiliz. Aurre-alfa itxian dago, beraz toki batzuetan latza da. Dibertigarria dirudiela uste baduzu, eskatu ondo eta agian goiz sartuko zara."]}],"quips":{"1":"Hitz bat. Ausarta. Agian gehiegi.","3":"Hiru hitz. Produktu-orri gehienak baino zintzoagoa jada.","8":"Zortzi hitz. Zutik egindako bilera bat baino laburragoa oraindik.","21":"Luzerak story point-ak dira, bide batez. Noski baietz.","55":"Berrogeita hamabost hitz. Bi txartel bukatu dira hau irakurtzen ari zinen bitartean.","144":"Hori da luzea. Ez dago 233rik. Agenteak ohera joan dira."}},"timeline":{"first-idea.name":"Lehen ideia","first-idea.line":"Lehen elkarrizketa, kodeik existitu aurretik.","first-board.name":"Lehen taula","first-board.line":"Bere eraikuntza bera jarraitzen duen taula: txartelak, zutabeak, arrastatu eta jaregin, proiektuak.","team-roles.name":"Taldea eta rolak","team-roles.line":"Agente-profilak, talde-txantiloiak, guneak eta nork zer egiten duen.","install.name":"Instalazioa eta bertsioak","install.line":"Lagun batek instala dezakeen zip bat, auto-eguneraketak, kanalak eta atzera egitea.","usage-saver.name":"Erabilera-aurrezlea","usage-saver.line":"Neurtu zenbat kostatzen diren exekuzioak, mantendu kodea arin, aurreztu zure muga.","friends.name":"Lagunak eta partekatzea","friends.line":"Mezu pribatuak, errele nahastua, gonbidapenak, rolak eta proiektu partekatuak.","languages.name":"Hizkuntzak","languages.line":"Pantailako testu guztiak hizkuntza-fitxategi batean, nederlandera eta flandestarra lehenengo.","ai-tester.name":"AA probatzailea","ai-tester.line":"Probatzaile batek entrega bakoitza aurretik egiaztatzen du eta ikusi duena erakusten du.","website.name":"Webgunea","website.line":"aigile.lol, teaser-a eta denbora-lerro hau.","streaming.name":"Txata eta streaming-a","streaming.line":"Discord, Twitch, OBS, streamer modua, GIFak eta emojiak.","no-ai.name":"AArik gabeko edizioa","no-ai.line":"AArik gabe programatzen dutenentzako taula, eta taula publikoak.","night-watch.name":"Gaueko zaintza","night-watch.line":"Zaindari batek eta Scrum Master batek taldeak zereginean mantentzen dituzte zu lo zaudela.","p-more.name":"Gainerako guztia","p-more.line":"Oraindik txandaren zain dauden ideia txikiagoak.","p-android.name":"Telefonoa eta Android","p-android.line":"Iritsi zure taulara telefonotik, gero Android aplikazio natibo batera.","p-release.name":"Alfa eta haratago","p-release.line":"Alfa itxia, webgune bizia, gero beta.","p-languages.name":"Hizkuntza gehiago","p-languages.line":"Ehun hizkuntza baino gehiago, eta murgiltze modua ikasleentzat.","p-engines.name":"AA motor gehiago","p-engines.line":"Aukeratu Claude, Codex edo Gemini agente bakoitzeko.","p-pro.name":"Praktika profesionala","p-pro.line":"Arrisku-etiketak, bateratze-ateak, intzidentzia-txartelak eta babes-hesiak.","p-self.name":"Zure zaintza","p-self.line":"Nekatuta modua, norberaren zaintzarako gogorarazpenak eta 4:20.","p-servers.name":"Zerbitzariak eta eskala","p-servers.line":"Zerbitzari-ezarpen orokorrak, rolak eta hazkundea planifikatzea.","p-livestream.name":"Streaming-aren gehigarriak","p-livestream.line":"Twitch txata, emoji pertsonalizatuak eta zuzeneko ikuspegi publikoa."},"words":{"button":"📖 Garatzaile-hitzak","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Bilatu hitz bat…","none":"Ez dago horrekin bat datorren hitzik.","close":"Itxi","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Proiektuaren kode-karpeta eta commit-en historia osoa, normalean GitHub-en ere gordetzen dena.","also":["repositorioa"]},{"id":"branch","g":"build","word":"Branch","text":"Kodeko lan-lerro bereizi bat, aldaketak bertsio nagusia ukitu gabe egiteko.","also":["branchak","branch-ak"]},{"id":"commit","g":"build","word":"Commit","text":"Kodearen argazki gordea, aldatutakoaren ohar labur batekin. Beti itzul zaitezke horietako batera.","also":["commitak","commit-ak"]},{"id":"push","g":"build","word":"Push","text":"Gordetako argazkiak (commit-ak) ordenagailu honetatik GitHub-era bidaltzea, babeskopia izan eta partekatuta egoteko."},{"id":"merge","g":"build","word":"Merge","text":"Branch baten aldaketak bertsio nagusian berriro batzea."},{"id":"pr","g":"build","word":"Pull request","text":"Branch baten aldaketak aztertu eta bertsio nagusian bateratzeko eskaera.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kodea txukuntzea egiten duena aldatu gabe: fitxategi txikiagoak, izen argiagoak, errepikapen gutxiago."},{"id":"bug","g":"build","word":"Bug","text":"Behar bezala ez dabilen zerbait.","also":["bugak","bug-ak"]},{"id":"test","g":"build","word":"Proba","text":"Amaitutako lan bat probatzea, eskatutakoa egiten duela egiaztatzeko, onartu aurretik.","also":["probak","probatu","probatzeko","probaren"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Bertsio berri bat martxan jartzea, adibidez jendeak erabiltzen duen zerbitzari batean."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Oraindik planifikatu gabeko ideiak eta lana. Ez da ezer lantzen Egiteko zutabera pasatu arte."},{"id":"sprint","g":"team","word":"Sprint","text":"Lan-tarte labur bat (askotan aste bat edo bi), amaitzeko adostutako txartel multzo batekin.","also":["sprintak","sprint-ak"]},{"id":"standup","g":"team","word":"Stand-up","text":"Egiaztapen azkar bat: talde-kide bakoitzak zer egin duen, zer egingo duen eta zerk geldiarazten duen.","also":["standup","stand-up-ak","standupak"]},{"id":"kanban","g":"team","word":"Kanban","text":"Zutabeak dituen taula (Egiteko, Egiten, Eginda), non txartelak ezkerretik eskuinera mugitzen diren lana egin ahala."},{"id":"wip","g":"team","word":"WIP muga","text":"Egiten ari den lana: zutabe batek izan beharko lukeen txartel kopuru handiena, taldeak gauzak amai ditzan gehiago hasi aurretik.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agente","text":"Zeregin batean bere kabuz lan egiten duen AI bat: kodea irakurtzen du, aldaketak egiten ditu, egiaztapenak exekutatzen ditu eta berri ematen du.","also":["agenteak"]},{"id":"token","g":"team","word":"Token","text":"AI erabilera zenbatzeko unitatea: gutxi gorabehera irakurritako edo idatzitako testuaren letra batzuk. Zenbat eta token gutxiago, orduan eta plan gehiago geratzen zaizu.","also":["token-ak","tokenak"]},{"id":"hook","g":"team","word":"Hook","text":"Une jakin batean bere kabuz exekutatzen den komando txiki bat, adib. AI saio bat hasten denean, taldeak zure iruzkinak entzun ditzan.","also":["hook-ak","hookak"]}]}};
